import { useState } from "react";

function FavColor() {
  const [color, setColor] = useState("Blue");

  return (
    <>
        <h1>My Favorite Color is {color}</h1>
        <button onClick={() => setColor("Red")}>Change to Red</button>
    </>
  );
}

export default FavColor;
